fn reverse_upto_k(s: &mut Vec<i32>, k: usize) {
    // Reverse the first k elements in place.
    // We only need to swap pairs (i, k-1-i) for i in [0..k/2).
    let half = k / 2;
    for i in 0..half {
        s.swap(i, k - 1 - i);
    }
}